public int[] matchingStrings(String[] strings, String[] queries) {
    int[] result = new int[queries.length];
    for (int i = 0; i < queries.length; i++) {
        int count = 0;
        for (String s : strings) {
            if (s.equals(queries[i])) {
                count++;
            }
        }
        result[i] = count;
    }
    return result;
}

